"""Render results/*.json into results/EVAL_REPORT.md."""
from __future__ import annotations

import json

from . import RESULTS_DIR

CONFIG_LABEL = {
    "schema_only": "A. 只給表名與欄位型別",
    "semantic_retry": "B. + dbt 語意層（欄位說明、商業規則、2 個範例）",
}


def _load(name: str) -> dict | None:
    path = RESULTS_DIR / name
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else None


def _pct(x: float) -> str:
    return f"{x * 100:.1f}%"


def render() -> str:
    out = ["# Evaluation report", "",
           "Generated by `python -m erp_copilot.evaluation report` from the JSON files in this folder.", ""]
    sql = _load("eval_sql_ollama.json")
    if sql:
        meta = sql["meta"]
        out += ["## Text-to-SQL (execution accuracy)", "",
                f"- Model: `{meta['model']}` via Ollama, temperature 0 · {meta['machine']} · {meta['generated_at']}",
                f"- Golden set: {next(iter(sql['configs'].values()))['summary']['n']} questions in Traditional Chinese "
                "(`eval/golden_sql.yaml`); a question counts as correct when the result set matches the reference "
                "query (row order ignored, numbers rounded to 2 decimals, extra helper columns allowed).", "",
                "| Prompt configuration | Executable | Correct (1st attempt) | Correct (with retry) | Fixed by retry | p50 / p95 latency |",
                "|---|---|---|---|---|---|"]
        for name, cfg in sql["configs"].items():
            s = cfg["summary"]
            with_retry = _pct(s["lenient_acc"]) if cfg["max_attempts"] > 1 else "—"
            out.append(f"| {CONFIG_LABEL.get(name, name)} | {_pct(s['executable_rate'])} | {_pct(s['first_attempt_acc'])} "
                       f"| {with_retry} | {s['fixed_by_retry'] if cfg['max_attempts'] > 1 else '—'} "
                       f"| {s['latency_p50_s']}s / {s['latency_p95_s']}s |")
        out += ["", "### Accuracy by difficulty", "", "| Configuration | Easy | Medium | Hard |", "|---|---|---|---|"]
        for name, cfg in sql["configs"].items():
            lv = cfg["summary"]["by_level"]
            out.append(f"| {CONFIG_LABEL.get(name, name)} | " + " | ".join(
                f"{_pct(lv[k]['lenient_acc'])} (n={lv[k]['n']})" for k in ("easy", "medium", "hard")) + " |")
        best = sql["configs"].get("semantic_retry") or next(iter(sql["configs"].values()))
        out += ["", "### Error analysis (best configuration)", "", "| Outcome | Count |", "|---|---|"]
        for k, v in sorted(best["summary"]["outcomes"].items(), key=lambda kv: -kv[1]):
            out.append(f"| {k} | {v} |")
        misses = [i for i in best["items"] if not i["lenient"]]
        if misses:
            out += ["", "Questions still answered incorrectly:", ""]
            for i in misses:
                reason = i["outcome"] + (f": {i['last_error'][:120]}" if i.get("last_error") and i["outcome"] != "wrong_result" else "")
                out.append(f"- `{i['id']}` {i['question']} — {reason}")
        out.append("")
    ret = _load("eval_retrieval.json")
    if ret:
        meta = ret["meta"]
        out += ["## SOP retrieval", "",
                f"- {ret['n']} questions (`eval/golden_sop.yaml`), {meta['chunks']} chunks; "
                f"{ret['modes'].get('bm25', {}).get('n_paraphrase', 0)} questions are paraphrased so they share few "
                f"words with the document. Embeddings: `{meta.get('embed_model')}` · {meta['generated_at']}", "",
                "| Retriever | Hit@1 | Hit@3 | MRR | Hit@3 on paraphrased questions |", "|---|---|---|---|---|"]
        label = {"bm25": "BM25 (character bigrams)", "dense": "Dense (embeddings)", "hybrid": "Hybrid (RRF of both)"}
        for mode, m in ret["modes"].items():
            out.append(f"| {label.get(mode, mode)} | {_pct(m['hit@1'])} | {_pct(m['hit@3'])} | {m['mrr']:.3f} "
                       f"| {_pct(m['paraphrase_hit@3'])} |")
        out.append("")
    return "\n".join(out)
